"""Write docs/facts.md: every citable fact, with the words that select it.

    python scripts/gen_facts_doc.py          # rewrite the page
    python scripts/gen_facts_doc.py --check  # exit 1 if the page is out of date (CI, tests)
"""

from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
OUT = ROOT / "docs" / "facts.md"

HEADER = """\
# Citable facts

<!-- Generated by scripts/gen_facts_doc.py from the domain modules; do not edit by hand. -->

Every fact a written proof can cite, by domain. A step can cite a fact in three ways:

```py
pl.claim(..., because=geo.similar_AA)          # the Python name
pl.claim(..., because="AA similarity")         # its label, or words that pick it out
pl.claim(..., because=["AA similarity", "hABC", "hA"])   # with the hypotheses it uses
```

A label selects its fact exactly. Other words are matched against all labels and names;
when two facts fit about equally well the step is refused with the candidates, never
guessed. Several facts may share one label (a *family*, such as the parts of CPCTC); citing
the label cites them all and Lean uses the one that fits. Search from Python with
`pl.search_facts("…")` or from the shell with `pyleanx facts …`.

**Source** says where the proof of the fact lives: *Mathlib* (a Mathlib theorem, used as
is) or *PyLeanX* (stated and proved in PyLeanX; its Lean proof is included in every file
that cites it and re-checked by Lean each time).

"""


def _cell(text: str) -> str:
    return text.replace("|", "\\|").replace("\n", " ")


def render() -> str:
    from pyleanx.fact_search import _catalog, domains
    from pyleanx.proofs import LibraryFact

    def how(module: str, prefix: str) -> str:
        parent, _, leaf = module.rpartition(".")
        return f"from {parent} import {leaf} as {prefix}" if parent else f"import {module}"

    titles = {d.prefix: (d.title, how(d.module, d.prefix)) for d in domains()}

    by_domain: dict[str, list] = {}
    for e in _catalog():
        by_domain.setdefault(e.qualified.split(".", 1)[0], []).append(e)
    total = sum(len(v) for v in by_domain.values())
    parts = [HEADER, f"{total} facts in {len(by_domain)} domains: "
             + ", ".join(f"[{titles[d][0]}](#{titles[d][0].lower().replace(' ', '-')})"
                         f" ({len(by_domain[d])})" for d in titles if d in by_domain)
             + ".\n"]
    for d, (title, imp) in titles.items():
        entries = by_domain.get(d)
        if not entries:
            continue
        parts.append(f"\n## {title}\n\n`{imp}`\n\n| Cite as | Label | Lean | Source |\n"
                     "|---|---|---|---|\n")
        for e in entries:
            src = "PyLeanX" if isinstance(e.obj, LibraryFact) else "Mathlib"
            lean = str(getattr(e.obj, "name", ""))
            parts.append(f"| `{e.qualified}` | {_cell(e.label)} | `{_cell(lean)}` | {src} |\n")
    return "".join(parts)


def main(argv: list[str]) -> int:
    text = render()
    if "--check" in argv:
        current = OUT.read_text(encoding="utf-8") if OUT.exists() else ""
        if current != text:
            print("docs/facts.md is out of date: run python scripts/gen_facts_doc.py")
            return 1
        return 0
    OUT.write_text(text, encoding="utf-8", newline="\n")
    print(f"wrote {OUT.relative_to(ROOT)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
